<script lang="ts">
  // A standing-in render of the workshop deck's first slide, drawn as DOM so it
  // paints with the prerendered HTML — no image, no webfont, no request. The
  // real deck only loads once the reader clicks through to the iframe.
  //
  // Geometry is mapped from the live deck: Slidev lays out on a 980-unit canvas,
  // so every position below is that measurement re-expressed in this 1600x900
  // viewBox. The lettering is generated by scripts/generate-title-outlines.mjs.
  import title from "./vibe-coding-title.json"

  // The deck's background is an animated WebGL spiral. Concentric rings read the
  // same at poster size for none of the cost; the real thing appears on click.
  const rings = [
    120, 168, 218, 270, 325, 383, 444, 508, 576, 648, 724, 804, 890,
  ]

  // Outline units -> viewBox units, so the title spans the deck's 35% of width.
  const titleScale = 561.5 / title.width
  const titleX = (1600 - 561.5) / 2
  // Baseline sits at 51.03% of slide height; the outline's own baseline is
  // 1487 units below its top.
  const titleY = 0.51033 * 900 - 1487 * titleScale
</script>

<svg
  class="block h-full w-full"
  viewBox="0 0 1600 900"
  preserveAspectRatio="xMidYMid slice"
  aria-hidden="true"
>
  <rect width="1600" height="900" fill="#f8f4e9" />

  <g fill="none" stroke="#94897a" stroke-opacity="0.22">
    {#each rings as r (r)}
      <circle cx="800" cy="450" {r} />
    {/each}
  </g>

  <path
    d={title.d}
    fill="#3a332a"
    transform="translate({titleX} {titleY}) scale({titleScale})"
  />

  <!-- Frozen rough.js instance of the deck's hand-drawn underline (360x24 box). -->
  <g transform="translate(506.1 502.2) scale(1.6325)">
    <path
      d="M6.303 10.683 C75.665 8.909, 143.613 8.101, 353.923 13.398 M8.064 12.943 C98.025 15.404, 189.978 15.750, 352.308 12.307"
      fill="none"
      stroke="#c25c3b"
      stroke-width="3.5"
      stroke-linecap="round"
    />
  </g>
</svg>
